_DURATION_RE = re.compile(
    r"^\s*(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?\s*$"
)


def parse_duration(s):
    """Parse a duration string such as '1h30m' into an integer number of seconds."""
    if not isinstance(s, str) or not s.strip():
        raise ValueError("invalid duration")

    match = _DURATION_RE.fullmatch(s)
    if match is None:
        raise ValueError("invalid duration")

    days, hours, minutes, seconds = match.groups()
    if all(value is None for value in (days, hours, minutes, seconds)):
        raise ValueError("invalid duration")

    total = 0
    if days is not None:
        total += int(days) * 24 * 60 * 60
    if hours is not None:
        total += int(hours) * 60 * 60
    if minutes is not None:
        total += int(minutes) * 60
    if seconds is not None:
        total += int(seconds)
    return total
